INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"6e3537f1-68f2-5f50-b07f-c8d37ddd8d5a","title":"Business Studies · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"What does a Gantt chart show in an action plan?","options":["Only the final profit figure","Only the owners' ages","Tasks and their timing along a timeline","A list of national laws"],"correct_index":2,"explanation":"A Gantt chart shows when tasks start and finish, helping track overlapping work and dependencies.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A presenter cannot answer a question confidently. What is the most professional response?","options":["Invent a statistic","Acknowledge the gap and offer to verify and follow up","Argue that questions are forbidden","Pretend the question was never asked"],"correct_index":1,"explanation":"Honesty protects credibility. Clarify the question and commit to checking reliable information rather than fabricating an answer.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which interview question is most appropriate for assessing a delivery planner?","options":["Describe how you would prioritise delayed deliveries","Which unrelated political party does your family support?","Why should we ignore your skills?","Will you accept unsafe work without questions?"],"correct_index":0,"explanation":"Job-relevant questions provide evidence of competence. Irrelevant or discriminatory questions do not fairly assess ability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why provide induction for a new employee?","options":["Avoid explaining the job","Explain the role, workplace procedures and safety expectations","Guarantee the employee never needs support","Replace all future communication"],"correct_index":1,"explanation":"Induction helps employees understand duties, colleagues, policies and safety. It is a starting point for ongoing support.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Two applicants have similar qualifications. An interviewer favours a friend without using job criteria. What is the best correction?","options":["Award the job privately to avoid paperwork.","Ask unrelated personal questions to justify the preference.","Use consistent job-related criteria, record evidence and manage the conflict of interest.","Treat friendship as proof of occupational competence."],"correct_index":2,"explanation":"Fair selection compares relevant evidence consistently and addresses conflicts of interest. Structured questions and documented scoring make the recommendation more defensible.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Mixed revision: Action plans, presentations and team development; Recruitment, selection and induction","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"8fa134e6-d90f-5c47-850f-91338ab2b644","title":"Business Studies · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"A business asks experts for anonymous opinions over several rounds. Which technique is this?","options":["Random sampling only","Delphi technique","A cash budget","Direct selling"],"correct_index":1,"explanation":"Delphi collects expert judgments, shares summaries and repeats rounds. Anonymity can reduce the influence of dominant individuals.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A salesperson knows a product has a defect but hides it. What is the ethical response?","options":["Disclose relevant facts and follow the remedy process","Conceal the defect to secure the sale","Blame the customer before use","Alter the receipt to hide evidence"],"correct_index":0,"explanation":"Honest disclosure and appropriate remedies support trust and ethical conduct. Professional behaviour does not mean maximising sales at any cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which interview question is most appropriate for assessing a delivery planner?","options":["Describe how you would prioritise delayed deliveries","Which unrelated political party does your family support?","Why should we ignore your skills?","Will you accept unsafe work without questions?"],"correct_index":0,"explanation":"Job-relevant questions provide evidence of competence. Irrelevant or discriminatory questions do not fairly assess ability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why provide induction for a new employee?","options":["Avoid explaining the job","Explain the role, workplace procedures and safety expectations","Guarantee the employee never needs support","Replace all future communication"],"correct_index":1,"explanation":"Induction helps employees understand duties, colleagues, policies and safety. It is a starting point for ongoing support.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Two applicants have similar qualifications. An interviewer favours a friend without using job criteria. What is the best correction?","options":["Award the job privately to avoid paperwork.","Ask unrelated personal questions to justify the preference.","Use consistent job-related criteria, record evidence and manage the conflict of interest.","Treat friendship as proof of occupational competence."],"correct_index":2,"explanation":"Fair selection compares relevant evidence consistently and addresses conflicts of interest. Structured questions and documented scoring make the recommendation more defensible.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Mixed revision: Marketing, production and ethical decisions; Recruitment, selection and induction","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"76b23e8d-c7c8-5c19-a913-503c4d397862","title":"Business Studies · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"A business asks experts for anonymous opinions over several rounds. Which technique is this?","options":["Random sampling only","Delphi technique","A cash budget","Direct selling"],"correct_index":1,"explanation":"Delphi collects expert judgments, shares summaries and repeats rounds. Anonymity can reduce the influence of dominant individuals.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A salesperson knows a product has a defect but hides it. What is the ethical response?","options":["Disclose relevant facts and follow the remedy process","Conceal the defect to secure the sale","Blame the customer before use","Alter the receipt to hide evidence"],"correct_index":0,"explanation":"Honest disclosure and appropriate remedies support trust and ethical conduct. Professional behaviour does not mean maximising sales at any cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"An entrepreneur tests a small version of a product before expanding. What does this demonstrate?","options":["A guarantee that failure is impossible","Avoidance of all decisions","Proof that planning is unnecessary","Managed risk-taking using evidence"],"correct_index":3,"explanation":"Testing assumptions can reduce uncertainty and reveal improvements. Entrepreneurial risk-taking can be informed and measured rather than reckless.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"During the storming stage, team members disagree about roles. What should a leader encourage?","options":["Constructive discussion and clarification of expectations","Permanent silence","Abandoning every shared goal","Ignoring all conflict"],"correct_index":0,"explanation":"Storming may involve conflict as members establish roles. Clarifying norms and responsibilities helps the team move towards more effective collaboration.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A pilot product succeeds with ten loyal customers. Which expansion recommendation is most defensible?","options":["Launch nationally because ten loyal users prove universal demand.","Cancel the product because small pilots never help.","Test demand in a broader target-market sample and update the action plan before scaling.","Copy the pilot result into every future forecast unchanged."],"correct_index":2,"explanation":"A pilot provides useful but limited evidence. A broader relevant sample, cost estimates and milestones help judge whether the result will transfer to the intended market.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Mixed revision: Marketing, production and ethical decisions; Action plans, presentations and team development","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"5c1e0183-1e35-5e47-a835-6526ff5764d7","title":"Economics · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 11","questions":[{"question":"Which best distinguishes economic development from economic growth?","options":["They are always identical measures","Growth means only a higher population","Development excludes education and health","Development includes living conditions and structural improvements, beyond output growth"],"correct_index":3,"explanation":"Growth concerns increased real output. Development considers broader changes such as living standards, capabilities and economic structure.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why do commercial banks assess borrowers before lending?","options":["To guarantee no loan can ever default","To remove the need for contracts","To evaluate repayment ability and credit risk","To lend every deposit to one person"],"correct_index":2,"explanation":"Credit assessment supports prudent lending and risk management, though it cannot eliminate defaults.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is a negative externality of factory air pollution?","options":["Only the factory's paid wage bill","A health cost borne by nearby residents that is not fully included in the factory's private costs","The firm's recorded profit","A benefit paid directly to every resident"],"correct_index":1,"explanation":"An external cost affects third parties outside the market transaction. Policy may seek to make decision-makers account for it.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which action supports sustainable resource use?","options":["Use every renewable resource faster than it regenerates","Treat pollution as having no cost","Harvest at a rate that allows replenishment while protecting ecosystems","Ignore future generations"],"correct_index":2,"explanation":"Sustainability considers current needs, ecosystem limits and future needs. Renewable does not mean unlimited at any rate of use.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A factory creates jobs but imposes unpriced health costs on neighbours. Which policy appraisal is strongest?","options":["Ignore health costs because they are outside the factory's accounts.","Close every factory without considering alternatives.","Compare employment benefits and external health costs, and assess measures that reduce pollution efficiently.","Treat all private costs as identical to all social costs."],"correct_index":2,"explanation":"A negative externality means some costs fall on third parties. A reasoned appraisal considers both benefits and social costs, including the effectiveness and consequences of corrective measures.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Mixed revision: Growth, development and banking; Globalisation and environmental sustainability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"6cb61fd5-aa44-5979-91c8-ed9d8537291d","title":"Economics · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 11","questions":[{"question":"A business sells 100 units at R20 each. Find total revenue.","options":["R120","R5","R2 000","R200"],"correct_index":2,"explanation":"Total revenue = price×quantity = 20×100=R2 000. Profit requires deducting costs, which are not provided here.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"If demand is price elastic, what usually happens to total revenue after a small price cut, other things equal?","options":["It must decrease","It increases","It stays zero","It becomes unrelated to quantity"],"correct_index":1,"explanation":"The percentage quantity increase exceeds the percentage price decrease, so total revenue increases within the elastic range.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What is a negative externality of factory air pollution?","options":["Only the factory's paid wage bill","A health cost borne by nearby residents that is not fully included in the factory's private costs","The firm's recorded profit","A benefit paid directly to every resident"],"correct_index":1,"explanation":"An external cost affects third parties outside the market transaction. Policy may seek to make decision-makers account for it.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which action supports sustainable resource use?","options":["Use every renewable resource faster than it regenerates","Treat pollution as having no cost","Harvest at a rate that allows replenishment while protecting ecosystems","Ignore future generations"],"correct_index":2,"explanation":"Sustainability considers current needs, ecosystem limits and future needs. Renewable does not mean unlimited at any rate of use.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A factory creates jobs but imposes unpriced health costs on neighbours. Which policy appraisal is strongest?","options":["Ignore health costs because they are outside the factory's accounts.","Close every factory without considering alternatives.","Compare employment benefits and external health costs, and assess measures that reduce pollution efficiently.","Treat all private costs as identical to all social costs."],"correct_index":2,"explanation":"A negative externality means some costs fall on third parties. A reasoned appraisal considers both benefits and social costs, including the effectiveness and consequences of corrective measures.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Mixed revision: Costs, revenue and elasticity; Globalisation and environmental sustainability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"9a013a11-5091-5b6c-8d83-7532db0fc01b","title":"Economics · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Economics","grade":"Grade 11","questions":[{"question":"A business sells 100 units at R20 each. Find total revenue.","options":["R120","R5","R2 000","R200"],"correct_index":2,"explanation":"Total revenue = price×quantity = 20×100=R2 000. Profit requires deducting costs, which are not provided here.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"If demand is price elastic, what usually happens to total revenue after a small price cut, other things equal?","options":["It must decrease","It increases","It stays zero","It becomes unrelated to quantity"],"correct_index":1,"explanation":"The percentage quantity increase exceeds the percentage price decrease, so total revenue increases within the elastic range.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why use real GDP instead of nominal GDP to compare output over time?","options":["It adjusts for price changes","It removes all population differences automatically","It measures happiness directly","It guarantees equal income"],"correct_index":0,"explanation":"Real GDP uses constant prices to help separate output changes from inflation. Per-capita measures additionally consider population.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which is a technical function of money?","options":["A guarantee of investment returns","Store of value","An unlimited natural resource","A replacement for every production input"],"correct_index":1,"explanation":"Money can serve as medium of exchange, unit of account and store of value. Inflation can reduce its purchasing power over time.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Nominal GDP rises 8% while the relevant price index rises 10%. Which claim needs correction?","options":["That price changes affect nominal comparisons.","That real GDP helps distinguish price and output changes.","That real output necessarily grew because nominal GDP increased.","That development includes more than GDP alone."],"correct_index":2,"explanation":"A nominal increase can be explained by higher prices. Under these indices the real factor is 1.08/1.10<1, suggesting a decline rather than proof of real growth.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Mixed revision: Costs, revenue and elasticity; Growth, development and banking","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"aefc6891-059d-5fcd-a245-324ba4fa760d","title":"Geography · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 11","questions":[{"question":"Why use more than GDP per capita when comparing development?","options":["Development includes health, education and distribution as well as income","GDP per capita proves everyone earns the average","Income is never relevant","Only land area determines development"],"correct_index":0,"explanation":"Development is multidimensional. Combine income with social indicators and consider inequality and local context.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What makes a development project more community-responsive?","options":["Outsiders assume every community has identical needs","The project never gathers feedback","Only publicity is measured","Local people help identify needs, decide priorities and evaluate outcomes"],"correct_index":3,"explanation":"Participation can improve relevance and accountability. Results should be evaluated with the people affected, not inferred from spending alone.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"What is a major environmental cost of coal-fired electricity?","options":["No emissions of any kind","Automatic restoration of mined land","Greenhouse gas emissions and air pollutants","Unlimited clean water production"],"correct_index":2,"explanation":"Coal combustion releases greenhouse gases and other pollutants. Full assessment also considers mining, water and management practices.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"How can overgrazing increase soil erosion?","options":["It always increases protective plant cover","It permanently stops rainfall","It eliminates all animal movement","It reduces vegetation cover, exposing soil to wind and runoff"],"correct_index":3,"explanation":"Loss of plant cover and roots leaves soil less protected. Grazing management should account for carrying capacity and recovery.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"An overgrazed hillside loses more soil than a vegetated one after storms. What investigation best tests vegetation's role?","options":["Compare unrelated slopes without measuring rainfall or soil.","Assume vegetation is the only possible cause.","Compare repeated soil-loss measurements on similar slopes with different cover, controlling other factors.","Use only a photograph taken before rain."],"correct_index":2,"explanation":"Similar slopes, soil and rainfall reduce competing explanations. Repeated measurements can reveal whether cover is associated with reduced runoff and erosion more reliably than a single observation.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Mixed revision: Development, trade and aid; Energy management and soil erosion","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"5864ecf8-eca3-511c-ab71-8d1b5777d3bc","title":"Geography · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 11","questions":[{"question":"A cuesta forms in strata with a gentle dip. Which slopes typically characterise it?","options":["Two identical vertical cliffs only","A flat surface with no slope","Only a volcanic crater","A steep scarp slope and a gentler dip slope"],"correct_index":3,"explanation":"Differential erosion of tilted resistant and less-resistant layers can produce an asymmetric ridge. The dip slope follows bedding inclination.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"On a topographic map, closely spaced contours generally indicate…","options":["A flat plain","A greater scale denominator by definition","A steep slope","A river flowing uphill"],"correct_index":2,"explanation":"For a constant contour interval, the same vertical change occurs over a shorter horizontal distance, indicating a steeper slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What is a major environmental cost of coal-fired electricity?","options":["No emissions of any kind","Automatic restoration of mined land","Greenhouse gas emissions and air pollutants","Unlimited clean water production"],"correct_index":2,"explanation":"Coal combustion releases greenhouse gases and other pollutants. Full assessment also considers mining, water and management practices.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"How can overgrazing increase soil erosion?","options":["It always increases protective plant cover","It permanently stops rainfall","It eliminates all animal movement","It reduces vegetation cover, exposing soil to wind and runoff"],"correct_index":3,"explanation":"Loss of plant cover and roots leaves soil less protected. Grazing management should account for carrying capacity and recovery.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"An overgrazed hillside loses more soil than a vegetated one after storms. What investigation best tests vegetation's role?","options":["Compare unrelated slopes without measuring rainfall or soil.","Assume vegetation is the only possible cause.","Compare repeated soil-loss measurements on similar slopes with different cover, controlling other factors.","Use only a photograph taken before rain."],"correct_index":2,"explanation":"Similar slopes, soil and rainfall reduce competing explanations. Repeated measurements can reveal whether cover is associated with reduced runoff and erosion more reliably than a single observation.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"Mixed revision: Rock structure, slopes and mass movement; Energy management and soil erosion","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"f1f46d9f-e911-5632-91ab-a218168d20ec","title":"Geography · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Geography","grade":"Grade 11","questions":[{"question":"A cuesta forms in strata with a gentle dip. Which slopes typically characterise it?","options":["Two identical vertical cliffs only","A flat surface with no slope","Only a volcanic crater","A steep scarp slope and a gentler dip slope"],"correct_index":3,"explanation":"Differential erosion of tilted resistant and less-resistant layers can produce an asymmetric ridge. The dip slope follows bedding inclination.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"On a topographic map, closely spaced contours generally indicate…","options":["A flat plain","A greater scale denominator by definition","A steep slope","A river flowing uphill"],"correct_index":2,"explanation":"For a constant contour interval, the same vertical change occurs over a shorter horizontal distance, indicating a steeper slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Which is an example of humanitarian aid?","options":["A routine export sale at market price","Emergency food and shelter after a disaster","A tax paid by a local shop","A share purchase by an investor"],"correct_index":1,"explanation":"Humanitarian aid addresses urgent needs and protects people in crises. Longer-term development assistance has different but sometimes connected aims.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why might reliance on one export commodity be risky?","options":["Its price can never change","Trade becomes completely independent of world markets","Global price changes can strongly affect income","It guarantees equal wealth"],"correct_index":2,"explanation":"Concentrated exports expose earnings to price and demand shocks. Diversification can reduce, though not eliminate, vulnerability.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Two countries have equal GDP per capita, but different life expectancy and schooling. Which judgement is justified?","options":["All development measures must therefore be identical.","The country with less schooling necessarily has more income.","Equal average income does not establish equal development or distribution.","Health measures cannot inform development comparisons."],"correct_index":2,"explanation":"GDP per capita is an average economic indicator. Health, education, inequality and access can differ, so use several indicators before judging development.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Mixed revision: Rock structure, slopes and mass movement; Development, trade and aid","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"0b157859-ac0a-5404-a774-8f5b9a887809","title":"History · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"History","grade":"Grade 11","questions":[{"question":"What distinguishes apartheid as a state policy after 1948?","options":["The first appearance of any racism anywhere","A systematic extension and enforcement of racial segregation and unequal rights","Universal equal citizenship from its start","An immediate end to earlier segregation"],"correct_index":1,"explanation":"Apartheid built on earlier discriminatory structures while expanding and systematising them. A comparison should identify both continuity and change.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is a single-cause explanation of the 1948 election result weak?","options":["It may ignore interacting political, social and electoral factors","Every historical event has exactly one cause","Only election dates matter","Evidence is unnecessary for elections"],"correct_index":0,"explanation":"Historical explanation should weigh several relevant factors and distinguish background conditions from immediate events.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why was the Sharpeville massacre in 1960 historically significant?","options":["It ended apartheid that day","It occurred after the 1994 election","It had no wider consequences","It intensified criticism of apartheid and affected the course of resistance and state repression"],"correct_index":3,"explanation":"The killing of protesters had major national and international repercussions. Explain the consequences with evidence and correct chronology.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What was a consequence of the Rivonia Trial for the liberation movement?","options":["Key leaders were imprisoned, affecting leadership and resistance strategies","Every political organisation became freely legal","Apartheid ended immediately","All international opposition disappeared"],"correct_index":0,"explanation":"The trial and imprisonment of leaders reshaped the struggle. It did not end resistance, which continued through different organisations and settings.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Two sources give different accounts of a protest. Which approach produces the strongest source-based answer?","options":["Average every number without checking how it was obtained.","Select the later source solely because it is later.","Identify precise agreements and differences, examine provenance and corroborate key claims.","Avoid all conclusions because disagreement exists."],"correct_index":2,"explanation":"Source disagreement is evidence to analyse. Dates, access to events, purposes and corroboration help judge particular claims rather than automatically accepting or rejecting a whole source.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"Mixed revision: Segregation and the apartheid state; Resistance, repression and source skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"b11f8686-b793-5635-b6d8-35f6781b0b72","title":"History · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"History","grade":"Grade 11","questions":[{"question":"Why are nineteenth-century racial hierarchies rejected by modern understandings of humanity?","options":["They are discriminatory social constructions, not a valid ranking of human worth or ability","They accurately rank every person's potential","They prove separate unequal human species","They require no scientific examination"],"correct_index":0,"explanation":"Historical racist ideas helped justify exclusion and violence. Modern evidence does not support ranking human populations by inherent worth or ability.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why compare sources from different nationalist movements?","options":["To prove every movement had identical goals","To remove historical context","To assume one source speaks for all members","To examine similarities, differences and the circumstances shaping each"],"correct_index":3,"explanation":"Comparative work needs evidence about aims, leadership, membership and context, including tensions within movements.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why was the Sharpeville massacre in 1960 historically significant?","options":["It ended apartheid that day","It occurred after the 1994 election","It had no wider consequences","It intensified criticism of apartheid and affected the course of resistance and state repression"],"correct_index":3,"explanation":"The killing of protesters had major national and international repercussions. Explain the consequences with evidence and correct chronology.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What was a consequence of the Rivonia Trial for the liberation movement?","options":["Key leaders were imprisoned, affecting leadership and resistance strategies","Every political organisation became freely legal","Apartheid ended immediately","All international opposition disappeared"],"correct_index":0,"explanation":"The trial and imprisonment of leaders reshaped the struggle. It did not end resistance, which continued through different organisations and settings.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Two sources give different accounts of a protest. Which approach produces the strongest source-based answer?","options":["Average every number without checking how it was obtained.","Select the later source solely because it is later.","Identify precise agreements and differences, examine provenance and corroborate key claims.","Avoid all conclusions because disagreement exists."],"correct_index":2,"explanation":"Source disagreement is evidence to analyse. Dates, access to events, purposes and corroboration help judge particular claims rather than automatically accepting or rejecting a whole source.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Mixed revision: Ideas of race and nationalisms; Resistance, repression and source skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"716ab74e-7afe-5cdf-8b5b-6d904ef8cb33","title":"History · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"History","grade":"Grade 11","questions":[{"question":"Why are nineteenth-century racial hierarchies rejected by modern understandings of humanity?","options":["They are discriminatory social constructions, not a valid ranking of human worth or ability","They accurately rank every person's potential","They prove separate unequal human species","They require no scientific examination"],"correct_index":0,"explanation":"Historical racist ideas helped justify exclusion and violence. Modern evidence does not support ranking human populations by inherent worth or ability.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why compare sources from different nationalist movements?","options":["To prove every movement had identical goals","To remove historical context","To assume one source speaks for all members","To examine similarities, differences and the circumstances shaping each"],"correct_index":3,"explanation":"Comparative work needs evidence about aims, leadership, membership and context, including tensions within movements.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why did apartheid legislation affect everyday life?","options":["It applied only to foreign trade","It had no relation to state power","It regulated areas such as residence, movement, education and political participation","It guaranteed equal services to all"],"correct_index":2,"explanation":"Interlocking laws enforced racial control across many parts of life. Specific examples strengthen an explanation of impact.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is a limitation of using a government statement alone to assess a policy's effects?","options":["Government documents contain no historical information","It must describe every outcome accurately","It removes the need for other evidence","It may present official justification while omitting affected people's experiences"],"correct_index":3,"explanation":"Official sources reveal intentions and public messaging. Compare them with implementation records and affected communities' testimony.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"A government statement says a segregation policy benefits everyone. Testimony from affected families describes restrictions. What should a historian do?","options":["Accept official status as proof that family accounts are false.","Assume disagreement makes both sources worthless.","Compare purpose, context and specific evidence, explaining differing perspectives.","Choose whichever source has the shorter text."],"correct_index":2,"explanation":"Different positions shape accounts, but claims can still be investigated. Explain each source's perspective and compare its evidence with legislation and further testimony.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"Mixed revision: Ideas of race and nationalisms; Segregation and the apartheid state","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"0c3fefad-8184-5499-a6e3-d95a0cf606d6","title":"Tourism · Grade 11 · Term 2 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 11","questions":[{"question":"An itinerary has activities at 09:00 and 09:15 in towns 80 km apart. What is its main problem?","options":["The font must be changed before anything else","Every route must cross a border","Travel time is unrealistic","It has too few currencies"],"correct_index":2,"explanation":"An itinerary must allow realistic travel and visiting time, plus breaks and contingencies. Geographic sequence and timing should work together.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A foreign guest struggles to understand a service explanation. What should staff do?","options":["Speak louder and refuse to clarify","Use clear language, check understanding and offer suitable support","Mock the guest's language","Assume agreement means understanding"],"correct_index":1,"explanation":"Respectful communication adapts language and checks the message was understood. Avoid stereotyping or treating language difficulty as lack of ability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why can tourism businesses benefit from reducing wasted water?","options":["It lowers avoidable resource use and can reduce costs","It guarantees no future drought","It removes the need for hygiene","It means guests never need drinking water"],"correct_index":0,"explanation":"Efficiency and conservation support resilience and sustainability. Maintain hygiene and essential services while reducing waste.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does a carbon footprint estimate?","options":["Only the size of a person's shoes","Greenhouse gas emissions associated with an activity, usually expressed as CO₂ equivalent","The number of trees in a brochure","A guarantee that an activity has no impact"],"correct_index":1,"explanation":"A footprint helps identify major emission sources and assess reductions. It depends on boundaries and calculation assumptions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A walking-tour project doubles visitor numbers while residents report crowding and damage. Which growth plan is strongest?","options":["Double visitors again because numbers alone define success.","Ignore residents because tourists are the only stakeholders.","Review carrying capacity, resident feedback and site protection alongside income.","Stop recording damage to improve the statistics."],"correct_index":2,"explanation":"Responsible enterprise evaluates visitor benefits with local wellbeing and conservation. Limits, scheduling and community input can protect the asset on which long-term tourism depends.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"Mixed revision: Itineraries, exchange rates and service; Tourism careers and sustainable enterprise","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[3,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"463f4f10-40c4-5975-a70a-ea0651a0ba08","title":"Tourism · Grade 11 · Term 3 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 11","questions":[{"question":"Why should a traveller compare the full car-rental quote rather than only the daily rate?","options":["Every quote includes unlimited free extras","Extra charges, insurance terms and mileage conditions affect total cost","The daily rate is always the final cost","Contract conditions never matter"],"correct_index":1,"explanation":"Check included kilometres, excesses, optional extras and other charges. A low headline rate may not be the cheapest suitable option.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which is a target-market decision?","options":["Designing a short affordable itinerary for local families","Buying fuel for every vehicle","Ignoring visitor research","Offering every product at an identical price by law"],"correct_index":0,"explanation":"Market selection informs product, price and promotion decisions. It starts with understanding the needs of a defined visitor group.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can tourism businesses benefit from reducing wasted water?","options":["It lowers avoidable resource use and can reduce costs","It guarantees no future drought","It removes the need for hygiene","It means guests never need drinking water"],"correct_index":0,"explanation":"Efficiency and conservation support resilience and sustainability. Maintain hygiene and essential services while reducing waste.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does a carbon footprint estimate?","options":["Only the size of a person's shoes","Greenhouse gas emissions associated with an activity, usually expressed as CO₂ equivalent","The number of trees in a brochure","A guarantee that an activity has no impact"],"correct_index":1,"explanation":"A footprint helps identify major emission sources and assess reductions. It depends on boundaries and calculation assumptions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A walking-tour project doubles visitor numbers while residents report crowding and damage. Which growth plan is strongest?","options":["Double visitors again because numbers alone define success.","Ignore residents because tourists are the only stakeholders.","Review carrying capacity, resident feedback and site protection alongside income.","Stop recording damage to improve the statistics."],"correct_index":2,"explanation":"Responsible enterprise evaluates visitor benefits with local wellbeing and conservation. Limits, scheduling and community input can protect the asset on which long-term tourism depends.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadata":{"term":3,"focus":"Mixed revision: Car rental, heritage and marketing; Tourism careers and sustainable enterprise","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,4],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}},{"id":"25d837c1-e81f-5796-8c34-52c775a8a879","title":"Tourism · Grade 11 · Term 4 selection · Set B: Mixed revision","subject":"Tourism","grade":"Grade 11","questions":[{"question":"Why should a traveller compare the full car-rental quote rather than only the daily rate?","options":["Every quote includes unlimited free extras","Extra charges, insurance terms and mileage conditions affect total cost","The daily rate is always the final cost","Contract conditions never matter"],"correct_index":1,"explanation":"Check included kilometres, excesses, optional extras and other charges. A low headline rate may not be the cheapest suitable option.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which is a target-market decision?","options":["Designing a short affordable itinerary for local families","Buying fuel for every vehicle","Ignoring visitor research","Offering every product at an identical price by law"],"correct_index":0,"explanation":"Market selection informs product, price and promotion decisions. It starts with understanding the needs of a defined visitor group.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A bank sells foreign currency at R20 per US dollar. Ignoring fees, how many dollars does R2 000 buy?","options":["US$40 000","US$1 980","US$20","US$100"],"correct_index":3,"explanation":"Divide rand by rand per dollar: 2 000/20=100 dollars. Fees and the appropriate buying or selling rate affect real transactions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tourist exchanges US$50 at R18 per dollar, with no fee. How many rand do they receive?","options":["R900","R2.78","R68","R90"],"correct_index":0,"explanation":"Multiply dollars by rand per dollar: 50×18=R900. Track the units to choose multiplication or division.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A visit ends at 10:00; the next begins at 10:30, 60 km away. Driving averages 60 km/h before parking time. What change is needed?","options":["Keep the plan because 60 km can always be driven in 30 minutes.","Delete the distance rather than revise the times.","Allow at least an hour of driving plus a practical arrival buffer.","Assume parking takes negative time."],"correct_index":2,"explanation":"At 60 km/h, 60 km requires one hour before parking or delays. The half-hour gap is infeasible; adjust the itinerary and include appropriate buffers.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Mixed grade revision drawn from the other two terms. Includes later-term topics; revisit after studying those topics. Questions are reused deliberately across revision sets.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Mixed revision: Car rental, heritage and marketing; Itineraries, exchange rates and service","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected grade revision from other terms, including later-term content. Not a second paper covering only the selected term.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"B","set_label":"Mixed grade revision","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses.","source_terms":[2,3],"atp_urls":["https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752"],"question_reuse":"Revision questions recur across term-focused and mixed sets; Set A and Set B within the same selection do not share questions."}}]$smartbridge$::jsonb)
